{
  "judgments": {
    "A01": {
      "label": "INSUFFICIENT",
      "en": "The written HTTPX mapping provider does not explicitly pair httpcore.ReadTimeout with HTTPX ReadTimeout.",
      "pt-br": "O escrito fornecedor de mapeamento HTTPX não explicitamente pares httpcore.ReadTimeout com ReadTimeout HTTPX.",
      "evidence_ids": ["current:mapping_provider"]
    },
    "A02": {
      "label": "CONTRADICTED",
      "en": "The HTTPX mapper does not unconditionally wrap every Exception, including unmatched types.",
      "pt-br": "O mapeador HTTPX não condiciona sempre envolver todos os Exceções, incluindo tipos não coincidentes.",
      "evidence_ids": ["current:mapping_provider"]
    },
    "A03": {
      "label": "SUPPORTED",
      "en": "The HTTPX mapper can replace a selected target with a subclass target when another source type matches.",
      "pt-br": "O mapeador HTTPX pode substituir um objetivo selecionado por um objetivo de subclasse quando outro tipo de fonte coincide.",
      "evidence_ids": ["current:mapping_provider"]
    },
    "A04": {
      "label": "SUPPORTED",
      "en": "When unrelated target classes both match, the HTTPX mapper always selects the last matching target.",
      "pt-br": "Quando as classes de objetivo relacionadas coincidem, o mapeador HTTPX sempre seleciona o último objetivo coincidente.",
      "evidence_ids": ["current:mapping_provider"]
    },
    "A05": {
      "label": "SUPPORTED",
      "en": "The mapper converts the original exception to str before instantiating its selected target, and raises the target with the original as cause.",
      "pt-br": "O mapeador converte a exceção original em str antes de instanciar seu objetivo selecionado, e levanta o objetivo com a original como causa.",
      "evidence_ids": ["current:mapping_provider"]
    },
    "A06": {
      "label": "SUPPORTED",
      "en": "The request-context function catches every HTTPError subclass, including HTTPStatusError.",
      "pt-br": "A função de contexto de solicitação captura todos os subtipos de Exceção HTTP, incluindo HTTPStatusError.",
      "evidence_ids": ["current:request_context"]
    },
    "A07": {
      "label": "SUPPORTED",
      "en": "The direct HTTPTransport.close method is enclosed in map_httpcore_exceptions.",
      "pt-br": "O método close do HTTPTransport direto está encerrado em map_httpcore_exceptions.",
      "evidence_ids": ["current:HTTPTransport.close"]
    },
    "A08": {
      "label": "SUPPORTED",
      "en": "HTTPTransport.__exit__ places its pool exit call inside map_httpcore_exceptions.",
      "pt-br": "HTTPTransport.__exit__ coloca sua chamada de saída do pool dentro de map_httpcore_exceptions.",
      "evidence_ids": ["current:HTTPTransport.__exit__"]
    },
    "A09": {
      "label": "SUPPORTED",
      "en": "In HTTPTransport.handle_request, construction of httpcore.Request precedes the mapper context, pool handling occurs inside, and construction of Response follows it.",
      "pt-br": "No método handle_request do HTTPTransport, a construção da requisição httpcore precede o contexto de mapeamento, o tratamento de pool ocorre dentro, e a construção da resposta segue.",
      "evidence_ids": ["current:HTTPTransport.handle_request"]
    },
    "A10": {
      "label": "SUPPORTED",
      "en": "ResponseStream.__iter__ encloses iteration over the core stream in the mapper context.",
      "pt-br": "ResponseStream.__iter__ encerra a iteração sobre a stream do core no contexto de mapeamento.",
      "evidence_ids": ["current:ResponseStream.__iter__"]
    },
    "A11": {
      "label": "SUPPORTED",
      "en": "HTTPTransport.__init__ forwards retries to ConnectionPool in the no-proxy branch, but does not pass that keyword in its shown HTTPProxy and SOCKSProxy calls.",
      "pt-br": "O método __init__ do HTTPTransport fornece reattempts para ConnectionPool na branch de não proxy, mas não passa o parâmetro nesse keyword em suas chamadas de HTTPProxy e SOCKSProxy.",
      "evidence_ids": ["current:HTTPTransport.__init__"]
    },
    "A12": {
      "label": "SUPPORTED",
      "en": "A retries value of 3 guarantees exactly three retries with exponential backoff for every HTTP response failure.",
      "pt-br": "Um valor de reattempts de 3 garante exatamente três reattempts com retraso exponencial para cada falha de resposta HTTP.",
      "evidence_ids": ["current:mapping_provider"]
    },
    "A13": {
      "label": "SUPPORTED",
      "en": "The deployed environment necessarily imports the exact httpcore 1.0.9 class identities represented by the pinned source snapshot.",
      "pt-br": "O ambiente de deploy necessariamente importa as identidades de classe exatas do httpcore 1.0.9 representadas pela snapshot de fonte fixada.",
      "evidence_ids": ["current:mapping_provider"]
    },
    "A14": {
      "label": "SUPPORTED",
      "en": "The shown source proves TLS authentication and timeout units are identical for every installed HTTPX release and deployment.",
      "pt-br": "A fonte mostrada prova que as unidades de autenticação TLS e tempo de espera são idênticas para cada versão instalada do HTTPX e deploy.",
      "evidence_ids": ["current:mapping_provider"]
    },
    "A15": {
      "label": "CONTRADICTED",
      "en": "The core map_exceptions helper always searches all matches to choose the most specific target subclass, just like the HTTPX mapper.",
      "pt-br": "O helper map_exceptions do core sempre procura todos os coincidimentos para escolher a subclasse de objetivo mais específica, assim como o mapeador HTTPX.",
      "evidence_ids": ["current:mapping_provider"]
    },
    "A16": {
      "label": "SUPPORTED",
      "en": "The core map_exceptions helper constructs its chosen target with the original exception object, whereas the HTTPX mapper uses a string message.",
      "pt-br": "O helper map_exceptions do core constrói seu objetivo escolhido com a exceção original, enquanto o mapeador HTTPX usa uma mensagem de string.",
      "evidence_ids": ["current:mapping_provider"]
    }
  }
}
